// Normalize ForexFactory weekly calendar into a single upsert statement.
// Mirrors services/data/news_fetcher.py exactly so behavior is identical.
function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function hashId(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return 'ff_' + h.toString(16);
}
const IMPACT = { high: 'HIGH', medium: 'MEDIUM', low: 'LOW' };
function eventsFrom(j) {
  if (Array.isArray(j)) return j;
  if (j && Array.isArray(j.body)) return j.body;
  if (j && Array.isArray(j.data)) return j.data;
  if (j && j.title) return [j]; // HTTP node already split a root array into items
  return [];
}

const rows = [];
for (const item of $input.all()) {
  for (const e of eventsFrom(item.json)) {
    const impact = IMPACT[String(e.impact || '').trim().toLowerCase()];
    if (!impact) continue;                 // drop Holiday / blank — not tradable
    const title = String(e.title || '').trim();
    if (!title || !e.date) continue;
    const d = new Date(e.date);            // ISO-8601 with offset, e.g. ...-05:00
    if (isNaN(d.getTime())) continue;
    // Store naive UTC to match TIMESTAMP WITHOUT TIME ZONE columns and the risk
    // engine's UTC window math. THIS is the #1 bug risk — keep it UTC.
    const scheduledAt = d.toISOString().slice(0, 19).replace('T', ' ');
    const currency = String(e.country || '').trim().toUpperCase() || 'UNKNOWN';
    const id = hashId(title + '|' + scheduledAt);
    rows.push('(' + [
      esc(id), esc(title), esc(impact), esc(currency), esc(scheduledAt),
      esc(e.forecast), esc(e.previous), esc(e.actual)
    ].join(',') + ', now())');
  }
}

let query;
if (rows.length === 0) {
  query = 'SELECT 1';
} else {
  query =
    'INSERT INTO "NewsEvent" ("id","title","impact","currency","scheduledAt","forecast","previous","actual","createdAt") VALUES ' +
    rows.join(',') +
    ' ON CONFLICT ("title","scheduledAt") DO UPDATE SET "actual"=EXCLUDED."actual","forecast"=EXCLUDED."forecast","impact"=EXCLUDED."impact","currency"=EXCLUDED."currency";';
}
return [{ json: { query, rowCount: rows.length } }];
